namespace {using namespace ii::gui;void check(bool v,const char* m){if(!v)throw std::runtime_error(m);}
template<class T>T take(ii::core::Result<T> r){if(!r)throw std::runtime_error(r.error().message);return std::move(*r);}void good(ii::core::Result<void> r){if(!r)throw std::runtime_error(r.error().message);}
struct Palette{WidgetColor focus{};friend bool operator==(const Palette&,const Palette&)=default;};struct Config{std::string label="Parent",icon_name,accessibility_name;double width=200,height=20,icon_size=18,chevron_size=16,corner_radius=5;std::int64_t count=-1;bool enabled=true,activatable=true,has_children=true,show_chevron=true,expanded=false;Palette palette;friend bool operator==(const Config&,const Config&)=default;};
struct Input{Config configuration;std::shared_ptr<const RasterImage> icon;std::shared_ptr<const void> icon_source;std::int64_t icon_revision=0;friend bool operator==(const Input&,const Input&)=default;};
struct Callbacks{std::function<void()> activated;std::function<void(bool)> expansion_changed;};struct Box{double x=0,y=0,width=0,height=0;};struct Geometry{Box surface,icon,label,count,chevron;bool show_icon=false,show_count=false,show_chevron=false;};struct Interaction{bool hovered=false,pressed=false,focused=false;};struct Visual{WidgetColor background{},focus{},text{};bool focused=false;};
struct Model{Config c;static bool validate(const Config& v){return v.width>0&&v.height>0;}bool set_configuration(Config v){if(!validate(v))return false;c=std::move(v);return true;}const Config& configuration()const{return c;}
 std::optional<Geometry> geometry(double w,double h)const{return Geometry{{0,0,w,h},{},{0,0,w-16,h},{},{w-16,0,16,h},false,false,c.has_children};}Visual visual(Interaction)const{return {};}std::optional<bool> toggle_expansion(){if(!c.has_children)return {};c.expanded=!c.expanded;return c.expanded;}};
struct Cache{inline static std::weak_ptr<int> retained;std::shared_ptr<int> marker=std::make_shared<int>(1);Cache(){retained=marker;}ii::core::Result<std::shared_ptr<const RasterImage>> resolve(std::string_view,std::shared_ptr<const void>,double){return rgba_image(1,1,{255,255,255,255});}};
struct Policy{using Input=::Input;using Model=::Model;using Rect=Box;using Color=WidgetColor;using Callbacks=::Callbacks;using IconCache=Cache;inline static constexpr double label_font_size=13,label_line_height=16,count_font_size=11,count_line_height=13,disabled_opacity=.35,focus_stroke=1.5,chevron_focus_radius=4;inline static constexpr unsigned label_font_weight=500,count_font_weight=400;inline static constexpr std::string_view expanded_icon="down",collapsed_icon="right";};
}
int main(){using View=ii::gui::BasicNativeHierarchyItem<Policy>;auto tree=std::make_shared<detail::WidgetState>([](ii::runtime::Task t){t();});auto host=take(tree->content_host({},"host",{200,20}));Input input;auto owner=std::make_shared<int>(1);std::weak_ptr<int> weak=owner;std::optional<View> view;int activated=0;
 good(host.set_content([&](WidgetBuilder& b)->ii::core::Result<void>{Callbacks cb;cb.activated=[&,held=owner]{++activated;};auto v=View::create(b,{},"row",input,std::move(cb));if(!v)return std::unexpected(v.error());view=*v;return {};}));owner.reset();(void)take(tree->drawing_snapshot({200,20}));good(view->row().activate());check(activated==1,"Hierarchy activation missing");good(host.clear_content());check(weak.expired()&&Cache::retained.expired()&&!view->options(),"Retired item retained resources");tree->close();}
